  levelJson: LevelJSON,
  iterations: number,
  deckSize?: number,
  seedOffset: number = 0,
  botConfig?: Partial<BotConfig>,
  onProgress?: (completed: number, total: number) => void
): SimulationMetrics {
  const bot = new MonteCarloBot(botConfig);

  let wins = 0;
  let closeWins = 0;
  let nearMisses = 0;
  let bombLosses = 0;
  let deckLosses = 0;
  let totalStreak = 0;
  let totalMoves = 0;

  const winRemainders: number[] = [];
  const remainderDistribution = [0, 0, 0, 0, 0, 0]; // 0, 1, 2, 3, 4, 5+

