      optimalDeckSize: bestStep ? bestStep.deckSize : levelJson.settings.cards_in_stack.length,
      bestMetrics: bestStep ? bestStep.metrics : runSimulationSync(levelJson, simCountPerStep, undefined, seedOffset, botConfig),
