}

export interface CalibrationResult {
  optimalDeckSize: number;
  bestMetrics: SimulationMetrics;
  history: CalibrationStep[];
  converged: boolean;
}

export class AutoCalibrator {
  public calibrate(
    levelJson: LevelJSON,
